function showModal(html){content.innerHTML=html;backdrop.classList.remove('hidden');}
function closeModal(){
 if(mockSession && !mockSession.submitted){
  if(!window.confirm('Exit this test? Your current attempt will not be scored.')) return;
  stopMockSectionTimer();mockSession=null;
 }
 if(seriesSession && !quizSubmitted){
  if(!window.confirm('Exit this test? Your current attempt will not be scored.')) return;
  stopQuizTimer();seriesSession=null;quizSubmitted=true;
 }else if(seriesSession && quizSubmitted){seriesSession=null}
 stopQuizTimer();document.onkeydown=null;backdrop.classList.add('hidden');content.innerHTML='';if(typeof setPrimaryNav==='function')setPrimaryNav(document.body.dataset.primaryView||'home');
}
$('#closeModal').addEventListener('click',closeModal);
backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
let toastTimer;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function bindDailyPlanner(){
 $('#plannerWeekStrip')?.addEventListener('click',e=>{const button=e.target.closest('[data-planner-date]');if(!button)return;const [y,m,d]=button.dataset.plannerDate.split('-').map(Number);plannerSelectedDate=new Date(y,m-1,d);plannerSelectedDate.setHours(0,0,0,0);renderDayPlanner()});
 $('#plannerTasks')?.addEventListener('change',e=>{const input=e.target.closest('[data-planner-task]');if(!input)return;const record=getDailyPlanRecord();record.completed[input.dataset.plannerTask]=input.checked;saveDailyPlanRecord(record);renderDayPlanner();renderStudyDashboard()});
 $('#plannerGkTopics')?.addEventListener('click',e=>{const button=e.target.closest('[data-planner-gk-topic]');if(!button)return;const record=getDailyPlanRecord(),topic=button.dataset.plannerGkTopic;record.gkTopics=record.gkTopics.includes(topic)?record.gkTopics.filter(x=>x!==topic):[...record.gkTopics,topic];saveDailyPlanRecord(record);renderDayPlanner()});
 $('#plannerPrevWeek')?.addEventListener('click',()=>{plannerSelectedDate.setDate(plannerSelectedDate.getDate()-7);renderDayPlanner()});
 $('#plannerNextWeek')?.addEventListener('click',()=>{plannerSelectedDate.setDate(plannerSelectedDate.getDate()+7);renderDayPlanner()});
 $('#plannerToday')?.addEventListener('click',()=>{plannerSelectedDate=new Date();plannerSelectedDate.setHours(0,0,0,0);renderDayPlanner()});
 $('#plannerResetDay')?.addEventListener('click',()=>{if(!window.confirm('Clear the checklist and GK selections for this day?'))return;saveDailyPlanRecord({completed:{},gkTopics:[]});renderDayPlanner();renderStudyDashboard();toast('This day’s checklist has been reset.')});
}

function getProfile(){try{return JSON.parse(localStorage.getItem('studyspark_profile')||'null')}catch{return null}}
function getStudyEvents(){try{return JSON.parse(localStorage.getItem('studyspark_activity')||'[]')}catch{return []}}
// Active study-time tracker. Time is counted only while this tab is visible and
// the learner has interacted recently; idle/background time is not counted.
const STUDY_TIME_KEY='studyspark_time_by_day_v1';
let studyLastInput=0,studyLastTick=Date.now(),studyTickHandle=null;
function studyDateKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function readStudyTime(){try{const value=JSON.parse(localStorage.getItem(STUDY_TIME_KEY)||'{}');return value&&typeof value==='object'?value:{}}catch{return {}}}
function writeStudyTime(data){try{localStorage.setItem(STUDY_TIME_KEY,JSON.stringify(data));return true}catch(e){console.warn('Study time could not be saved',e);return false}}
function formatStudyDuration(seconds){seconds=Math.max(0,Math.floor(seconds||0));const h=Math.floor(seconds/3600),m=Math.floor((seconds%3600)/60),s=seconds%60;return h?`${h}h ${m}m`:`${m}m ${s}s`}
function getStudyPeriodTotals(){const data=readStudyTime(),now=new Date(),today=studyDateKey(now);let todaySec=0,weekSec=0,monthSec=0,allSec=0;const daily=[];for(let i=0;i<30;i++){const d=new Date(now);d.setHours(0,0,0,0);d.setDate(d.getDate()-i);const key=studyDateKey(d),sec=Math.max(0,Number(data[key])||0);allSec+=sec;if(key===today)todaySec=sec;if(i<7)weekSec+=sec;monthSec+=sec;if(i<7)daily.push({key,label:d.toLocaleDateString('en-IN',{weekday:'short',day:'numeric'}),seconds:sec})}return {todaySec,weekSec,monthSec,allSec,daily}}
function studyTimeTick(){const now=Date.now(),elapsed=Math.min(30_000,Math.max(0,now-studyLastTick));studyLastTick=now;if(document.visibilityState==='visible'&&studyLastInput&&now-studyLastInput<5*60*1000&&elapsed>0){const data=readStudyTime(),key=studyDateKey();data[key]=Math.max(0,Number(data[key])||0)+Math.round(elapsed/1000);writeStudyTime(data);const live=$('#profileLiveToday');if(live)live.textContent=formatStudyDuration(getStudyPeriodTotals().todaySec);renderStudyDashboard();}}
function markStudyActive(){studyLastInput=Date.now()}
function startStudyTimeTracker(){if(studyTickHandle)return;['pointerdown','keydown','scroll','touchstart','click'].forEach(type=>window.addEventListener(type,markStudyActive,{passive:true}));document.addEventListener('visibilitychange',()=>{studyLastTick=Date.now();if(document.visibilityState==='visible')markStudyActive()});studyTickHandle=setInterval(studyTimeTick,15000);studyLastTick=Date.now()}
function openStudyProfile(){const profile=getProfile(),totals=getStudyPeriodTotals(),daily=totals.daily;const bars=daily.slice().reverse().map(day=>`<div class="study-time-day"><span>${day.label}</span><i><b style="width:${Math.min(100,totals.weekSec?day.seconds/Math.max(1,...daily.map(x=>x.seconds))*100:0)}%"></b></i><strong>${formatStudyDuration(day.seconds)}</strong></div>`).join('');showModal(`<div class="study-profile"><div class="eyebrow">YOUR LEARNING SPACE</div><h2 id="modalTitle">${escapeHTML(profile?.name||'Your profile')}</h2><p class="study-profile-subtitle">Your study activity, saved on this browser.</p><div class="study-time-grid"><article><span>TODAY</span><strong id="profileLiveToday">${formatStudyDuration(totals.todaySec)}</strong></article><article><span>LAST 7 DAYS</span><strong>${formatStudyDuration(totals.weekSec)}</strong></article><article><span>LAST 30 DAYS</span><strong>${formatStudyDuration(totals.monthSec)}</strong></article><article><span>RECORDED TOTAL</span><strong>${formatStudyDuration(totals.allSec)}</strong></article></div><section class="study-time-history"><h3>Last 7 days</h3>${bars||'<p>No study time recorded yet.</p>'}</section><div class="study-profile-note">The timer counts active time while this tab is visible and you've interacted within the last 5 minutes. Your data stays in this browser and is not synced across devices. Create or log in to your profile on this device to personalise it.</div><div class="study-profile-actions"><button class="btn btn-outline" id="profileLoginAction">${profile?'Change profile':'Create profile'}</button><button class="btn btn-primary" id="profileCloseAction">Done</button></div></div>`);$('#profileCloseAction')?.addEventListener('click',closeModal);$('#profileLoginAction')?.addEventListener('click',()=>{closeModal();showAuth('signup')})}
function trackStudyEvent(type){
 try{
  const events=getStudyEvents();
  const safeEvents=Array.isArray(events)?events:[];
  safeEvents.push({type:String(type||'study'),at:new Date().toISOString()});
  localStorage.setItem('studyspark_activity',JSON.stringify(safeEvents.slice(-200)));
 }catch(error){console.warn('Study activity could not be saved in this browser.',error)}
}
function plannerDayKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
const dailyPlanTasks=[
 {id:'fullMock',group:'Practice & reading',title:'Attempt 1 full mock test',detail:'Complete one full SSC-style paper under exam conditions.',meta:'1 full mock',icon:'▣',tone:'violet'},
 {id:'editorial',group:'Practice & reading',title:'Read one editorial',detail:'Read carefully, note the central argument and 3–5 useful expressions.',meta:'1 editorial',icon:'▤',tone:'blue'},
 {id:'vocabulary',group:'Practice & reading',title:'Vocabulary practice',detail:'Revise new words, meanings, synonyms, antonyms and usage.',meta:'Daily word set',icon:'Aa',tone:'pink'},
 {id:'english',group:'Core subjects',title:'English practice',detail:'Grammar, comprehension, error spotting and sentence improvement.',meta:'2 hours',icon:'Aa',tone:'pink'},
 {id:'maths',group:'Core subjects',title:'Mathematics practice',detail:'Concept revision followed by timed quantitative questions.',meta:'2 hours',icon:'∑',tone:'blue'},
 {id:'reasoning',group:'Core subjects',title:'Reasoning practice',detail:'Series, analogy, coding-decoding, relations and analytical questions.',meta:'1 hour · suggested',icon:'◇',tone:'green'},
 {id:'staticGk',group:'GK & review',title:'Static GK study',detail:'Study one or more GK areas using your notes and source material.',meta:'1 hour · suggested',icon:'◎',tone:'orange'},
 {id:'currentAffairs',group:'GK & review',title:'Current affairs revision',detail:'Review important news, dates, reports, schemes and appointments.',meta:'30 min · suggested',icon:'◷',tone:'teal'},
 {id:'mockAnalysis',group:'GK & review',title:'Analyse the mock and update error log',detail:'Review wrong and guessed answers; write down the topic to revise.',meta:'30 min · suggested',icon:'↗',tone:'violet'}
];
const plannerGkChoices=['Polity','History','Geography','Economy','General Science','Criminal Law'];
let plannerSelectedDate=new Date();plannerSelectedDate.setHours(0,0,0,0);
function getDailyPlanData(){try{return JSON.parse(localStorage.getItem('studyspark_daily_plan_v1')||'{}')}catch{return {}}}
function getDailyPlanRecord(date=plannerSelectedDate){const data=getDailyPlanData();const raw=data[plannerDayKey(date)]||{};return {completed:raw.completed&&typeof raw.completed==='object'?raw.completed:{},gkTopics:Array.isArray(raw.gkTopics)?raw.gkTopics:[]}}
function saveDailyPlanRecord(record,date=plannerSelectedDate){const data=getDailyPlanData();data[plannerDayKey(date)]={completed:record.completed||{},gkTopics:record.gkTopics||[]};try{localStorage.setItem('studyspark_daily_plan_v1',JSON.stringify(data));return true}catch(err){console.warn('Could not save daily planner data',err);toast('Browser storage is full; your latest change may not be saved.');return false}}
function plannerCompletedCount(date){const record=getDailyPlanRecord(date);return dailyPlanTasks.filter(task=>record.completed[task.id]).length}
function plannerStartOfWeek(date){const d=new Date(date);d.setHours(0,0,0,0);const offset=(d.getDay()+6)%7;d.setDate(d.getDate()-offset);return d}
function renderDayPlanner(){
 const selectedLabel=$('#plannerSelectedDate'),hint=$('#plannerDateHint');
 if(selectedLabel)selectedLabel.textContent=plannerSelectedDate.toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 const todayKey=plannerDayKey(new Date());if(hint)hint.textContent=plannerDayKey(plannerSelectedDate)===todayKey?'Your plan for today':`Checklist for ${plannerSelectedDate.toLocaleDateString('en-IN',{weekday:'long'})}`;
 const strip=$('#plannerWeekStrip');if(strip){strip.innerHTML='';const start=plannerStartOfWeek(plannerSelectedDate);for(let i=0;i<7;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=plannerDayKey(d),done=plannerCompletedCount(d),pct=Math.round(done/dailyPlanTasks.length*100);const b=document.createElement('button');b.type='button';b.className=`daily-week-day${key===plannerDayKey(plannerSelectedDate)?' selected':''}${key===todayKey?' is-today':''}${done===dailyPlanTasks.length?' is-complete':''}`;b.dataset.plannerDate=key;b.setAttribute('aria-pressed',key===plannerDayKey(plannerSelectedDate)?'true':'false');b.innerHTML=`<span>${d.toLocaleDateString('en-IN',{weekday:'short'}).toUpperCase()}</span><strong>${d.getDate()}</strong><small>${done}/${dailyPlanTasks.length}</small><i><b style="width:${pct}%"></b></i>`;strip.appendChild(b)}}
 const record=getDailyPlanRecord(),completed=dailyPlanTasks.filter(task=>record.completed[task.id]).length,pct=Math.round(completed/dailyPlanTasks.length*100);
 const count=$('#plannerProgressCount');if(count)count.textContent=`${completed} / ${dailyPlanTasks.length} tasks done`;
 const message=$('#plannerProgressMessage');if(message)message.textContent=completed===dailyPlanTasks.length?'All tasks completed — excellent consistency.':completed===0?'Start with one task. Build from there.':`${dailyPlanTasks.length-completed} tasks left for this day. Keep your pace steady.`;
 const fill=$('#plannerProgressFill');if(fill)fill.style.width=`${pct}%`;
 const tasksBox=$('#plannerTasks');if(tasksBox){let html='';let currentGroup='';dailyPlanTasks.forEach(task=>{if(task.group!==currentGroup){currentGroup=task.group;html+=`<div class="daily-task-group-label">${currentGroup}</div>`}const checked=!!record.completed[task.id];html+=`<label class="daily-task-card ${checked?'is-done':''}"><input type="checkbox" data-planner-task="${task.id}" ${checked?'checked':''}><span class="daily-task-check" aria-hidden="true">✓</span><span class="daily-task-icon ${task.tone}">${task.icon}</span><span class="daily-task-copy"><b>${task.title}</b><small>${task.detail}</small></span><span class="daily-task-meta">${task.meta}</span></label>`});tasksBox.innerHTML=html}
 const topics=$('#plannerGkTopics');if(topics){$$('[data-planner-gk-topic]',topics).forEach(button=>{const active=record.gkTopics.includes(button.dataset.plannerGkTopic);button.classList.toggle('active',active);button.setAttribute('aria-pressed',active?'true':'false')})}
 const total=$('#plannerTaskTotal');if(total)total.textContent=`${dailyPlanTasks.length} daily tasks`;
}
function renderStudyDashboard(){
 const now=new Date(),today=new Date(now);today.setHours(0,0,0,0);const todayRecord=getDailyPlanRecord(today);const completed=dailyPlanTasks.filter(task=>todayRecord.completed[task.id]).length;const goal=dailyPlanTasks.length;const pct=Math.round(completed/goal*100);const todayKey=plannerDayKey(today);
 const ring=$('#progressRing');if(ring)ring.style.background=`conic-gradient(#a88cff 0 ${pct}%,#29334f ${pct}% 100%)`;
 const percent=$('#progressPercent');if(percent)percent.textContent=`${pct}%`;
 const count=$('#goalCount');if(count)count.textContent=`${completed} / ${goal}`;
 const headline=$('#progressHeadline');if(headline)headline.textContent=completed===0?'Ready for your first study task?':completed===goal?'Daily plan completed — great work!':'You’re building today’s momentum!';
 const message=$('#progressMessage');if(message)message.textContent=completed===goal?'You completed your full daily checklist. Keep the rhythm going.':`${completed} of ${goal} daily tasks completed. ${goal-completed} still to go.`;
 const steps=$('#dailySteps');if(steps){steps.innerHTML='';for(let i=0;i<goal;i++){const step=document.createElement('span');step.textContent=i+1;step.className=i<completed?'done':'';step.setAttribute('aria-label',`Task ${i+1}${i<completed?' completed':' not completed'}`);steps.appendChild(step)}}
 const bars=$('#weeklyBars'),labels=$('#weekDayLabels');if(bars){bars.innerHTML='';if(labels)labels.innerHTML='';const start=new Date(today);start.setDate(today.getDate()-6);for(let i=0;i<7;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=plannerDayKey(d),dayCount=plannerCompletedCount(d),height=dayCount?Math.max(12,Math.round(dayCount/goal*100)):4;const bar=document.createElement('i');bar.style.height=`${height}%`;bar.title=`${d.toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'short'})}: ${dayCount}/${goal} tasks completed`;bar.setAttribute('aria-label',bar.title);if(key===todayKey)bar.classList.add('today');bars.appendChild(bar);if(labels){const label=document.createElement('span');label.textContent=d.toLocaleDateString('en-IN',{weekday:'short'}).slice(0,2);if(key===todayKey)label.className='today';labels.appendChild(label)}}}
 const timeTotals=getStudyPeriodTotals();
 const todayTime=$('#dashboardTodayTime');if(todayTime)todayTime.textContent=formatStudyDuration(timeTotals.todaySec);
 const weekTime=$('#dashboardWeekTime');if(weekTime)weekTime.textContent=formatStudyDuration(timeTotals.weekSec);
 const monthTime=$('#dashboardMonthTime');if(monthTime)monthTime.textContent=formatStudyDuration(timeTotals.monthSec);
 const status=$('#saveStatusTitle');if(status)status.textContent=completed?'Daily progress saved':'Ready to track your day';const sub=$('#saveStatusText');if(sub)sub.textContent='Checklist saved on this browser only';
}

function showAuth(mode='signup'){
  const isSignup=mode==='signup';
  showModal(`<div class="eyebrow">YOUR LEARNING SPACE</div><h2 id="modalTitle">${isSignup?'Create your demo profile':'Welcome back'}</h2><p>${isSignup?'Use a nickname to personalise this local demo.':'Enter the nickname you used on this device.'}</p><form id="authForm"><label class="modal-label" for="nick">Nickname</label><input class="modal-input" id="nick" required maxlength="24" placeholder="e.g. StudyStar" value="${getProfile()?.name||''}"><button class="btn btn-primary" type="submit" style="width:100%">${isSignup?'Create demo profile':'Continue'} →</button></form><p class="modal-note">Prototype only: this does not create a secure account or sync between devices. Real login needs a backend.</p>`);
  $('#authForm').addEventListener('submit',e=>{e.preventDefault();const name=$('#nick').value.trim();if(!name)return;localStorage.setItem('studyspark_profile',JSON.stringify({name}));closeModal();toast(`Welcome, ${name}! Demo profile saved on this device.`);renderLeaderboard()});
}
$('#loginBtn').addEventListener('click',()=>showAuth('login'));
$('#dashboardProfileBtn')?.addEventListener('click',openStudyProfile);
$('#signupBtn').addEventListener('click',()=>showAuth('signup'));
$('#ctaSignup')?.addEventListener('click',()=>showAuth('signup'));
$$('[data-quiz]').forEach(b=>b.addEventListener('click',()=>startQuiz(b.dataset.quiz)));
$('#reviewNotes')?.addEventListener('click',()=>{const library=$('#resourceLibraryDetails');if(library)library.open=true;openPrimaryView('home');setTimeout(()=>$('#resources')?.scrollIntoView({behavior:'smooth',block:'start'}),40);toast('Learning library opened.')});
$('#quickQuiz')?.addEventListener('click',()=>openCglMockHub('full'));
quizzes.algebraRevisionFastTest = {
 title: 'Maths Revision Fast Test — Algebra', subject: 'Maths', category: 'Maths Revision · Algebra', timeLimitMinutes: 12,
 questions: [
  {q:'If a + b = 11 and ab = 24, find a² + b².',options:['71','73','75','97'],answer:1,explain:'Use a² + b² = (a + b)² − 2ab = 11² − 48 = 73.'},
  {q:'If a − b = 6 and ab = 7, find a² + b².',options:['46','48','50','52'],answer:2,explain:'Use a² + b² = (a − b)² + 2ab = 36 + 14 = 50.'},
  {q:'If p + q = 9 and pq = 14, find p³ + q³.',options:['333','341','351','369'],answer:2,explain:'p³ + q³ = (p + q)³ − 3pq(p + q) = 729 − 378 = 351.'},
  {q:'If (m + n)² − (m − n)² = 80, what is mn?',options:['16','18','20','24'],answer:2,explain:'The difference of the two squares is 4mn. Thus 4mn = 80 and mn = 20.'},
  {q:'If x + 1/x = 4, find x² + 1/x².',options:['12','14','16','18'],answer:1,explain:'Square the given relation: x² + 2 + 1/x² = 16. Therefore the required value is 14.'},
  {q:'If x + 1/x = 5, find x³ + 1/x³.',options:['100','105','110','115'],answer:2,explain:'Use t³ − 3t with t = x + 1/x. The value is 125 − 15 = 110.'},
  {q:'If x + 1/x = 3, find x⁴ + 1/x⁴.',options:['43','45','47','49'],answer:2,explain:'First x² + 1/x² = 3² − 2 = 7. Then x⁴ + 1/x⁴ = 7² − 2 = 47.'},
  {q:'If x − 1/x = 3, find x² + 1/x².',options:['9','10','11','13'],answer:2,explain:'Square: x² − 2 + 1/x² = 9. Hence x² + 1/x² = 11.'},
  {q:'If x + 1/x = 3 and x > 1, what is x − 1/x?',options:['−√5','√5','5','1/√5'],answer:1,explain:'(x − 1/x)² = (x + 1/x)² − 4 = 5. Since x > 1, the difference is positive: √5.'},
  {q:'If x² + 1/x² = 14, find x⁴ + 1/x⁴.',options:['192','194','196','198'],answer:1,explain:'Square the given expression: x⁴ + 2 + 1/x⁴ = 196. So the answer is 194.'},
  {q:'If a + b = 5 and ab = 4, find a³ + b³.',options:['55','60','65','75'],answer:2,explain:'a³ + b³ = (a + b)³ − 3ab(a + b) = 125 − 60 = 65.'},
  {q:'If a + b = 5 and ab = 4, find a⁴ + b⁴.',options:['241','249','257','273'],answer:2,explain:'a² + b² = 25 − 8 = 17. Then a⁴ + b⁴ = 17² − 2(4²) = 289 − 32 = 257.'},
  {q:'Which is the complete factorisation of a¹⁶ − b¹⁶ over the integers?',options:['(a − b)(a + b)(a² + b²)(a⁴ + b⁴)(a⁸ + b⁸)','(a − b)(a + b)(a⁸ − b⁸)','(a² − b²)(a⁴ − b⁴)','(a − b)¹⁶'],answer:0,explain:'Repeatedly apply difference of squares: a¹⁶ − b¹⁶ = (a⁸ − b⁸)(a⁸ + b⁸), then factor a⁸ − b⁸, a⁴ − b⁴ and a² − b².'},
  {q:'For x² − 10x + k to be a perfect square, what is k?',options:['20','24','25','any positive value'],answer:2,explain:'Compare with (x − 5)² = x² − 10x + 25. Therefore k = 25.'},
  {q:'What value of k makes 4x² + 12x + k a perfect square?',options:['6','8','9','12'],answer:2,explain:'4x² + 12x + 9 = (2x + 3)², so k = 9.'},
  {q:'If a + b = 7 and ab = 10, find a³ + b³.',options:['123','133','143','153'],answer:1,explain:'a³ + b³ = 7³ − 3(10)(7) = 343 − 210 = 133.'},
  {q:'If a + b + c = 0, which relation is always true?',options:['a³ + b³ + c³ = 0','a³ + b³ + c³ = 3abc','a² + b² + c² = abc','a + b = c'],answer:1,explain:'The identity a³ + b³ + c³ − 3abc = (a + b + c)(a² + b² + c² − ab − bc − ca) becomes zero when the sum is zero.'},
  {q:'If a + b + c = 9 and a² + b² + c² = 31, find ab + bc + ca.',options:['21','23','25','27'],answer:2,explain:'(a + b + c)² = a² + b² + c² + 2(ab + bc + ca). Thus 81 = 31 + 2S, so S = 25.'},
  {q:'For real a, b and c, if a² + b² + c² − ab − bc − ca = 0, what follows?',options:['a + b + c = 0','a = b = c','abc = 0','exactly two variables are equal'],answer:1,explain:'Twice the expression is (a − b)² + (b − c)² + (c − a)². A sum of real squares is zero only when all three differences are zero.'},
  {q:'For a = 1, b = 2 and c = 3, evaluate a³ + b³ + c³ − 3abc.',options:['12','18','20','36'],answer:1,explain:'1 + 8 + 27 − 3(1)(2)(3) = 36 − 18 = 18.'},
  {q:'If x = a − b, y = b − c and z = c − a, find x + y + z.',options:['0','a + b + c','abc','1'],answer:0,explain:'Add the definitions: (a − b) + (b − c) + (c − a) = 0 by cancellation.'},
  {q:'An algebraic expression is symmetric in a and b when:',options:['it changes sign after swapping a and b','its value remains unchanged after swapping a and b','a and b must be equal','it contains only squares'],answer:1,explain:'A symmetric expression is unchanged when the variables are interchanged. This differs from a cyclic expression, which follows a rotation of variables.'},
  {q:'A cyclic expression in a, b and c is typically one that:',options:['uses only a², b² and c²','is unchanged under every possible rearrangement','follows the same pattern when a→b, b→c and c→a','requires a = b = c'],answer:2,explain:'A cyclic form follows a fixed rotation of the variables: a to b, b to c and c to a.'},
  {q:'If (x + 5)/(x − 5) = 3/2, find x.',options:['20','25','30','35'],answer:1,explain:'Cross-multiply: 2(x + 5) = 3(x − 5). Thus 2x + 10 = 3x − 15 and x = 25.'},
  {q:'If (a + b)/(a − b) = 3, then a/b equals:',options:['1','2','3','4'],answer:1,explain:'a + b = 3a − 3b, so 4b = 2a. Hence a/b = 2 (with b ≠ 0).'},
  {q:'If (a + b)² + (a − b)² = 200, find a² + b².',options:['50','75','100','200'],answer:2,explain:'The left side equals 2(a² + b²). Therefore a² + b² = 200/2 = 100.'},
  {q:'If a + b = 13 and a − b = 5, find a² + b².',options:['87','92','97','102'],answer:2,explain:'a² + b² = [(a + b)² + (a − b)²]/2 = (169 + 25)/2 = 97.'},
  {q:'If an identity is claimed for every real x, which substitution can disprove it if the two sides give different values?',options:['Only x = 0 can be used','Any one allowed value, such as x = 1','A substitution can never disprove an identity','Only a negative value can be used'],answer:1,explain:'One valid counterexample is enough to disprove a universal identity. However, checking a few values cannot prove that an identity is true for every x.'}
 ]
};

quizzes.algebraCompleteRevisionTest = {
 title:'Algebra Complete Revision Test', subject:'Maths', category:'Maths Revision · Algebra', timeLimitMinutes:35,
 questions:[
  {q:'If (a + b)² + (a − b)² = 180, find a² + b².',options:['45','80','90','180'],answer:2,explain:'The sum of the two squares is 2(a² + b²). Hence a² + b² = 180/2 = 90.'},
  {q:'If a + b = 13 and a − b = 5, find ab.',options:['34','36','40','42'],answer:1,explain:'ab = [(a + b)² − (a − b)²]/4 = (169 − 25)/4 = 36.'},
  {q:'If a + b = 9 and ab = 14, find a⁴ + b⁴.',options:['2,401','2,417','2,501','2,609'],answer:1,explain:'First a² + b² = 9² − 2(14) = 53. Then a⁴ + b⁴ = 53² − 2(14²) = 2,417.'},
  {q:'If a + b = 8 and ab = 12, find a² + ab + b².',options:['52','60','64','76'],answer:0,explain:'a² + ab + b² = (a + b)² − ab = 64 − 12 = 52.'},
  {q:'Which is the complete difference-of-squares factorisation of m¹⁶ − n¹⁶?',options:['(m − n)(m + n)(m² + n²)(m⁴ + n⁴)(m⁸ + n⁸)','(m − n)¹⁶','(m² − n²)(m⁴ − n⁴)','(m − n)(m⁸ + n⁸)'],answer:0,explain:'Repeatedly factor the difference of squares until reaching m² − n², then split that final factor.'},
  {q:'For x² − 14x + k to be a perfect square, what is k?',options:['7','14','28','49'],answer:3,explain:'Complete the square by adding (−14/2)² = 49: x² − 14x + 49 = (x − 7)².'},
  {q:'Find k so that 9x² + 12x + k is a perfect square.',options:['2','4','6','9'],answer:1,explain:'9x² + 12x + 4 = (3x + 2)², so k = 4.'},
  {q:'The expression 4u² + 12uv + 9v² is equal to:',options:['(2u − 3v)²','(2u + 3v)²','(4u + 9v)²','(u + 3v)²'],answer:1,explain:'It matches A² + 2AB + B² with A = 2u and B = 3v.'},
  {q:'If (x − 2)² + (y + 3)² = 0 for real x and y, find x + y.',options:['−5','−1','1','5'],answer:1,explain:'Each real square must be zero, so x = 2 and y = −3. Their sum is −1.'},
  {q:'Which is the completed-square form of 3x² + 12x + 12?',options:['3(x + 2)²','3(x + 4)²','(3x + 2)²','3(x − 2)²'],answer:0,explain:'Factor out 3: 3(x² + 4x + 4) = 3(x + 2)².'},
  {q:'If 4x + 3y = 7 and 3x − 4y = 1, find x² + y².',options:['1','2','4','5'],answer:1,explain:'Square and add: (4x + 3y)² + (3x − 4y)² = 25(x² + y²) = 7² + 1² = 50. Thus x² + y² = 2.'},
  {q:'If a + b = 7 and ab = 10, find a³ + b³.',options:['103','123','133','153'],answer:2,explain:'a³ + b³ = (a + b)³ − 3ab(a + b) = 343 − 210 = 133.'},
  {q:'If a − b = 5 and ab = 4, find a³ − b³.',options:['125','145','165','185'],answer:3,explain:'a³ − b³ = (a − b)[(a − b)² + 3ab] = 5(25 + 12) = 185.'},
  {q:'Factorise 8x³ − 27y³.',options:['(2x − 3y)(4x² + 6xy + 9y²)','(2x + 3y)(4x² − 6xy + 9y²)','(2x − 3y)(4x² − 6xy + 9y²)','(2x + 3y)(4x² + 6xy + 9y²)'],answer:0,explain:'Use A³ − B³ = (A − B)(A² + AB + B²), with A = 2x and B = 3y.'},
  {q:'Recognise the identity: 8p³ + 36p²q + 54pq² + 27q³.',options:['(2p − 3q)³','(2p + 3q)³','(p + 3q)³','(2p + q)³'],answer:1,explain:'The four terms match A³ + 3A²B + 3AB² + B³ for A = 2p and B = 3q.'},
  {q:'For non-zero a and b, (a³ + b³)/(a² − ab + b²) equals:',options:['a − b','a + b','ab','a² + b²'],answer:1,explain:'Factor a³ + b³ = (a + b)(a² − ab + b²), then cancel the common non-zero factor.'},
  {q:'Which factorisation is correct for x⁶ − y⁶?',options:['(x − y)(x + y)(x² + xy + y²)(x² − xy + y²)','(x − y)⁶','(x² − y²)(x² + xy + y²)','(x³ − y³)²'],answer:0,explain:'Write x⁶ − y⁶ = (x³ − y³)(x³ + y³), then factor each cubic.'},
  {q:'Evaluate (x + 1)(x² + 1)(x⁴ + 1) when x = 2.',options:['127','255','256','511'],answer:1,explain:'The product with the missing (x − 1) factor gives x⁸ − 1. Since x − 1 = 1 at x = 2, the value is 2⁸ − 1 = 255.'},
  {q:'For an odd positive integer n, which factor always divides aⁿ + bⁿ?',options:['a − b','a + b','a² + b²','ab'],answer:1,explain:'For odd n, the sum of nth powers is divisible by a + b.'},
  {q:'If x + 1/x = 6, find x² + 1/x².',options:['32','34','36','38'],answer:1,explain:'Square the given relation: x² + 2 + 1/x² = 36. Subtract 2.'},
  {q:'If x − 1/x = 4, find x² + 1/x².',options:['14','16','18','20'],answer:2,explain:'(x − 1/x)² = x² + 1/x² − 2 = 16, so the required sum is 18.'},
  {q:'If x + 1/x = 5/2 and x > 1, find x − 1/x.',options:['1/2','1','3/2','2'],answer:2,explain:'The square of the difference is (5/2)² − 4 = 9/4. Since x > 1, choose the positive root 3/2.'},
  {q:'If x + 1/x = 3, find x³ + 1/x³.',options:['9','15','18','27'],answer:2,explain:'Use t³ − 3t with t = 3: 27 − 9 = 18.'},
  {q:'For real non-zero x, if x + 1/x = 2, find x⁴ + 1/x⁴.',options:['0','1','2','4'],answer:2,explain:'x + 1/x = 2 implies x = 1. Therefore x⁴ + 1/x⁴ = 2.'},
  {q:'If x − 1/x = −5, find x² + 1/x².',options:['21','23','25','27'],answer:3,explain:'Square the difference: x² + 1/x² − 2 = 25. Add 2 to obtain 27.'},
  {q:'If x + 1/x = 5, find x⁴ + 1/x⁴.',options:['523','525','527','529'],answer:2,explain:'First x² + 1/x² = 25 − 2 = 23. Then x⁴ + 1/x⁴ = 23² − 2 = 527.'},
  {q:'If x² + 1/x² = 3, find x⁴ + 1/x⁴.',options:['5','7','9','11'],answer:1,explain:'Square the given relation: x⁴ + 2 + 1/x⁴ = 9. Subtract 2.'},
  {q:'For real x, y and z, if x² + y² + z² = 0, then:',options:['x + y + z = 1','x = y = z = 0','xyz = 1','exactly one variable is zero'],answer:1,explain:'Each square is non-negative. Their sum can be zero only when all three variables are zero.'},
  {q:'If (2x − 6)² + (3y + 9)² = 0 for real x and y, find x + y.',options:['−3','−1','0','3'],answer:2,explain:'Both brackets must be zero: x = 3 and y = −3. Therefore x + y = 0.'},
  {q:'For real p, q and r, if p² + q² + r² − pq − qr − rp = 0, what follows?',options:['p + q + r = 0','p = q = r','pqr = 0','p = −q'],answer:1,explain:'Twice the expression is (p − q)² + (q − r)² + (r − p)². All differences must be zero.'},
  {q:'If a + b + c = 9 and a² + b² + c² = 35, find ab + bc + ca.',options:['21','22','23','24'],answer:2,explain:'81 = 35 + 2S, so S = 23.'},
  {q:'If a + b + c = 0, then a³ + b³ + c³ equals:',options:['0','abc','2abc','3abc'],answer:3,explain:'The three-variable identity gives a³ + b³ + c³ − 3abc = 0 when the sum is zero.'},
  {q:'If x = a − b, y = b − c and z = c − a, then x + y + z is:',options:['−1','0','1','a + b + c'],answer:1,explain:'The terms cancel: a − b + b − c + c − a = 0.'},
  {q:'If x² + y² = 8 and xy = 3, find x⁴ + x²y² + y⁴.',options:['49','55','61','73'],answer:1,explain:'Use (x² + y²)² − (xy)² = 64 − 9 = 55.'},
  {q:'If x² + y² = 10 and xy = 3, find x⁴ + y⁴.',options:['82','88','91','100'],answer:0,explain:'x⁴ + y⁴ = (x² + y²)² − 2x²y² = 100 − 18 = 82.'},
  {q:'If (m + n)/(m − n) = 5/3, find m/n.',options:['2','3','4','5'],answer:2,explain:'3(m + n) = 5(m − n), so 8n = 2m and m/n = 4.'},
  {q:'If (x + 4)/(x − 4) = 3, find x.',options:['4','6','8','12'],answer:2,explain:'x + 4 = 3x − 12, so 2x = 16 and x = 8.'},
  {q:'If p/q = 3/2, find (p + q)/(p − q).',options:['1','3','5','7'],answer:2,explain:'Put p = 3k and q = 2k. The ratio becomes 5k/k = 5.'},
  {q:'Which expression is symmetric in a and b?',options:['a² − b²','a² + b² + ab','a²b − ab²','a³ − b³'],answer:1,explain:'Swapping a and b leaves a² + b² + ab unchanged.'},
  {q:'Which expression follows a cyclic pattern under a → b, b → c, c → a?',options:['a² + b² + c²','ab + bc + ca','a²b + b²c + c²a','a + b + c'],answer:2,explain:'The terms rotate in order: a²b becomes b²c, b²c becomes c²a, and c²a becomes a²b.'},
  {q:'A single allowed substitution gives different values on the two sides of a claimed identity. What does this show?',options:['The identity is proved','The identity is false as a universal claim','The identity is true for positive x','Nothing can be concluded'],answer:1,explain:'One valid counterexample disproves a claim that is supposed to hold for every allowed value.'},
  {q:'Find the polynomial HCF of x⁶ + 1 and x⁴ − 1.',options:['x − 1','x² + 1','x² − 1','x⁴ + 1'],answer:1,explain:'x⁶ + 1 = (x² + 1)(x⁴ − x² + 1), and x⁴ − 1 = (x² − 1)(x² + 1). The common factor is x² + 1.'},
  {q:'Simplify (x² − 25)/(x² + 10x + 25), where the expression is defined.',options:['(x + 5)/(x − 5)','(x − 5)/(x + 5)','x − 5','x + 5'],answer:1,explain:'Factor to (x − 5)(x + 5)/(x + 5)², then cancel one common factor; x ≠ −5.'},
  {q:'If a + b = 5 and a² + b² = 13, find a³ + b³.',options:['25','30','35','45'],answer:2,explain:'ab = [(a + b)² − (a² + b²)]/2 = (25 − 13)/2 = 6. Then a³ + b³ = 125 − 3(6)(5) = 35.'},
  {q:'If a + b = 11 and a − b = 3, find a² + b².',options:['55','60','65','70'],answer:2,explain:'a² + b² = [(a + b)² + (a − b)²]/2 = (121 + 9)/2 = 65.'},
  {q:'If 2a + 3b = 13 and ab = 6, find 4a² + 9b².',options:['73','85','97','109'],answer:2,explain:'(2a + 3b)² = 4a² + 9b² + 12ab. Thus 169 = required value + 72, giving 97.'},
  {q:'If a + 2b = 9 and 2ab = 10, find a³ + 8b³.',options:['369','429','459','489'],answer:2,explain:'Set A = a and B = 2b. Then A + B = 9 and AB = 10. A³ + B³ = 9³ − 3(10)(9) = 459.'},
  {q:'If x + y = 10 and xy = 21, find x⁴ + y⁴.',options:['2,382','2,422','2,482','2,522'],answer:2,explain:'x² + y² = 100 − 42 = 58. Then x⁴ + y⁴ = 58² − 2(21²) = 3,364 − 882 = 2,482.'},
  {q:'If a + b + c = 6, ab + bc + ca = 11 and abc = 6, find a³ + b³ + c³.',options:['24','30','36','42'],answer:2,explain:'Use a³ + b³ + c³ = s³ − 3sq + 3r = 216 − 198 + 18 = 36.'},
  {q:'For real a, b and c, the identity a³ + b³ + c³ − 3abc equals:',options:['(a + b + c)(a² + b² + c²)','(a + b + c)(a² + b² + c² − ab − bc − ca)','(a − b − c)(a² + b² + c²)','(a + b + c)³'],answer:1,explain:'This is the standard three-variable cubic factorisation. The second factor can also be written as one-half the sum of the three squared differences.'},
  {q:'Evaluate (0.2³ + 0.1³)/(0.2² − 0.2×0.1 + 0.1²).',options:['0.03','0.3','3','0.9'],answer:1,explain:'Use (a³ + b³)/(a² − ab + b²) = a + b. The value is 0.2 + 0.1 = 0.3.'},
  {q:'Evaluate 998 × 1002 without long multiplication.',options:['999,996','999,998','1,000,004','1,000,996'],answer:0,explain:'Write the factors as (1000 − 2)(1000 + 2) = 1000² − 2² = 999,996.'}
 ]
};


function quizTimeLimitSeconds(count){if(activeQuiz&&Number.isFinite(activeQuiz.timeLimitMinutes))return Math.max(60,Math.round(activeQuiz.timeLimitMinutes*60));if(activeQuiz&&activeQuiz.title==='Constitution Articles — Mega Test')return 1440*60;if(activeQuiz&&activeQuiz.title==='Constitutional Amendments — Mega Test')return 180*60;if(activeQuiz&&/^120 Rules · Part [1-4]/.test(activeQuiz.title))return 120*60;if(count<=10)return 5*60;if(count<=30)return 15*60;if(count<=90)return 30*60;return 60*60}
function formatQuizTime(seconds){const s=Math.max(0,seconds|0);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function stopQuizTimer(){if(quizTimerInterval){clearInterval(quizTimerInterval);quizTimerInterval=null}}
function startQuizTimer(useSavedTime=true){
 stopQuizTimer();quizSubmitted=false;
 const starting=useSavedTime&&seriesSession&&Number.isFinite(seriesSession.remainingSeconds)?Math.max(0,seriesSession.remainingSeconds):quizTimeLimitSeconds(activeQuiz.questions.length);
 if(seriesSession){seriesSession.remainingSeconds=starting;seriesSession.paused=false}
 quizDeadline=Date.now()+starting*1000;
 quizTimerInterval=setInterval(()=>{
  const remaining=Math.max(0,Math.ceil((quizDeadline-Date.now())/1000));
  if(seriesSession)seriesSession.remainingSeconds=remaining;
  const el=$('#quizTimer');if(el){el.textContent=formatQuizTime(remaining);el.classList.toggle('timer-warning',remaining<=60)}
  if(remaining<=0){stopQuizTimer();finishQuiz(true)}
 },250);
}
function pauseSeriesAttempt(){
 if(!seriesSession||quizSubmitted||seriesSession.paused)return;
 seriesSession.remainingSeconds=Math.max(0,Math.ceil((quizDeadline-Date.now())/1000));
 seriesSession.paused=true;stopQuizTimer();renderSeriesExam();
}
function resumeSeriesAttempt(){
 if(!seriesSession||quizSubmitted)return;
 if(!seriesSession.paused)return renderSeriesExam();
 seriesSession.paused=false;startQuizTimer(true);renderSeriesExam();
}
function backFromSeriesAttempt(){
 if(!seriesSession||quizSubmitted)return;
 if(!seriesSession.paused)pauseSeriesAttempt();
 const title=activeQuiz?.title||'';
 if(/120 Rules/i.test(title)){openMockGrammarPicker();return}
 if(/Amendment/i.test(title)){openPolityQuizBrowser('amendments');return}
 if(/Article/i.test(title)){openPolityQuizBrowser('articles');return}
 if(/Lecture 1/i.test(title)){openCglMockHub('topics','General Awareness','Polity');return}
 openCglMockHub('topics',activeQuiz?.subject||'All subjects');
}
function startQuiz(key){
 if(/^grammar120part[1-4]$/.test(key)) activeQuiz=buildGrammarPartQuiz(Number(key.slice(-1)));
 else {
  const base=quizzes[key];
  if(base&&/^polity(Article|Amendment|Lecture)/.test(key)){
   const shuffledQuestions=base.questions.map(q=>{const pairs=q.options.map((label,i)=>({label,correct:i===q.answer}));const shuffled=shuffleArray(pairs);return {...q,options:shuffled.map(x=>x.label),answer:shuffled.findIndex(x=>x.correct)}});
   activeQuiz={...base,questions:/^polityLecture/.test(key)?shuffleArray(shuffledQuestions):shuffledQuestions};
  }else activeQuiz=base;
 }
 if(!activeQuiz||!Array.isArray(activeQuiz.questions)||!activeQuiz.questions.length){toast('This practice set is not available yet.');return}
 currentQuestion=0;quizScore=0;quizAnswers=new Array(activeQuiz.questions.length).fill(null);picked=false;quizSubmitted=false;
 seriesSession={review:new Array(activeQuiz.questions.length).fill(false),visited:new Array(activeQuiz.questions.length).fill(false),remainingSeconds:quizTimeLimitSeconds(activeQuiz.questions.length),paused:false};
 startQuizTimer(true);renderSeriesExam();
}
function renderSeriesExam(){
 if(!activeQuiz||!seriesSession||quizSubmitted)return;
 const questions=activeQuiz.questions,total=questions.length,qi=currentQuestion,q=questions[qi];
 seriesSession.visited[qi]=true;
 const answers=quizAnswers,review=seriesSession.review;
 const attempted=answers.filter(v=>v!==null&&v!==undefined).length,marked=review.filter(Boolean).length;
 const progress=Math.round(attempted/total*100),remaining=seriesSession.paused?seriesSession.remainingSeconds:Math.max(0,Math.ceil((quizDeadline-Date.now())/1000));
 const paletteSize=100,palettePage=Math.floor(qi/paletteSize),paletteStart=palettePage*paletteSize,paletteEnd=Math.min(total,paletteStart+paletteSize);
 const palette=Array.from({length:paletteEnd-paletteStart},(_,offset)=>{const i=paletteStart+offset;return `<button class="mock-question-dot ${i===qi?'current':''} ${answers[i]!==null&&answers[i]!==undefined?'answered':''} ${review[i]?'review':''} ${!seriesSession.visited[i]?'unvisited':''}" data-series-question="${i}" aria-label="Question ${i+1}">${i+1}</button>`}).join('');
 const category=activeQuiz.category||activeQuiz.subject||'Topic practice';
 const pauseOverlay=seriesSession.paused?`<div class="exam-pause-overlay" role="dialog" aria-modal="true" aria-label="Test paused"><div class="exam-pause-card"><span class="exam-pause-kicker">ATTEMPT PAUSED</span><h2>Take a break.</h2><p>Your answers and remaining time are saved in this open attempt.</p><button class="exam-pause-resume" id="seriesResumeOverlay">Resume test <span>→</span></button><button class="exam-pause-back" id="seriesBackOverlay">Back to test menu</button></div></div>`:'';
 showModal(`<div class="mock-exam-shell series-exam-shell"><header class="mock-exam-topbar"><div class="mock-exam-brand"><button class="mock-exam-back" id="seriesBackToMenu" aria-label="Back to test menu">← Back</button><span class="mock-exam-mark">✦</span><div><b>${escapeHTML(activeQuiz.title)}</b><small>Test series · ${escapeHTML(category)} · StudySpark Hub</small></div></div><div class="mock-exam-top-actions"><div class="mock-exam-timer"><span>TEST TIME LEFT</span><strong id="quizTimer">${formatQuizTime(remaining)}</strong></div><button class="mock-exam-submit-top mock-pause-toggle" id="seriesPauseToggle">${seriesSession.paused?'Resume':'Pause'}</button><button class="mock-exam-submit-top" id="seriesExitExam">Exit</button><button class="mock-exam-submit-top series-submit-top" id="seriesSubmitTop">Submit test</button></div></header><main class="mock-exam-main"><div class="mock-exam-section-head"><div><span class="mock-exam-kicker">TEST SERIES · ${escapeHTML(String(category).toUpperCase())}</span><h2>${escapeHTML(activeQuiz.title)}</h2><p>Choose your answers, mark questions for review and submit when you are ready.</p></div><div class="mock-exam-section-stats"><strong>${attempted}<small> / ${total}</small></strong><span>Answered</span></div></div><div class="mock-exam-progress"><span style="width:${progress}%"></span></div><div class="mock-exam-layout"><section class="mock-question-panel"><div class="mock-question-meta"><span>QUESTION ${String(qi+1).padStart(2,'0')} OF ${total}</span><span>${answers[qi]===null||answers[qi]===undefined?'NOT ANSWERED':'ANSWER SAVED'}</span></div><h3>${escapeHTML(q.q)}</h3>${q.source?`<p class="mock-question-source">Reference: ${escapeHTML(q.source)}</p>`:''}<div class="mock-exam-options">${q.options.map((o,i)=>`<button class="mock-exam-option ${answers[qi]===i?'selected':''}" data-series-answer="${i}"><span>${String.fromCharCode(65+i)}</span><b>${escapeHTML(o)}</b>${answers[qi]===i?'<i>✓</i>':''}</button>`).join('')}</div><div class="mock-exam-question-actions"><button id="seriesMarkReview" class="mock-light-action ${review[qi]?'is-marked':''}">${review[qi]?'★ Marked for review':'☆ Mark for review'}</button><button id="seriesClearAnswer" class="mock-light-action">Clear response</button></div></section><aside class="mock-question-palette"><div class="mock-palette-head"><b>Question palette</b><span>${attempted}/${total} answered</span></div><div class="mock-palette-legend"><span><i class="legend-answered"></i> Answered</span><span><i class="legend-review"></i> Review</span><span><i class="legend-empty"></i> Not answered</span></div><div class="mock-question-grid">${palette}</div>${total>100?`<div class="mock-palette-pager"><button id="seriesPalettePrev" ${palettePage===0?'disabled':''}>← 100</button><span>${paletteStart+1}–${paletteEnd} / ${total}</span><button id="seriesPaletteNext" ${paletteEnd>=total?'disabled':''}>100 →</button></div>`:''}<div class="mock-palette-summary"><div><span>Answered</span><b>${attempted}</b></div><div><span>Review</span><b>${marked}</b></div><div><span>Remaining</span><b>${total-attempted}</b></div></div></aside></div></main><div class="mock-edge-navigation" aria-label="Question navigation"><button class="mock-edge-nav-btn previous" id="seriesEdgePrevious" ${qi===0?'disabled':''} aria-label="Previous question"><span>‹</span><small>PREV</small></button><button class="mock-edge-nav-btn next" id="seriesEdgeNext" aria-label="${qi===total-1?'Submit test':'Next question'}"><small>${qi===total-1?'SUBMIT':'NEXT'}</small><span>${qi===total-1?'✓':'›'}</span></button></div><footer class="mock-exam-footer"><button class="mock-footer-btn" id="seriesPrevious" ${qi===0?'disabled':''}>← Previous</button><div class="mock-footer-centre"><span>QUESTION ${qi+1} / ${total}</span><small>Independent practice · No negative marking</small></div>${qi===total-1?'<button class="mock-footer-btn mock-footer-primary" id="seriesNext">Submit test →</button>':'<button class="mock-footer-btn mock-footer-primary" id="seriesNext">Next →</button>'}</footer>${pauseOverlay}</div>`);
 $('#seriesExitExam')?.addEventListener('click',()=>{if(window.confirm('Exit this test? Your current attempt will not be scored.')){stopQuizTimer();seriesSession=null;quizSubmitted=true;closeModal()}});
 $('#seriesPauseToggle')?.addEventListener('click',()=>seriesSession.paused?resumeSeriesAttempt():pauseSeriesAttempt());
 $('#seriesResumeOverlay')?.addEventListener('click',resumeSeriesAttempt);
 $('#seriesBackToMenu')?.addEventListener('click',backFromSeriesAttempt);
 $('#seriesBackOverlay')?.addEventListener('click',backFromSeriesAttempt);
 $('#seriesEdgePrevious')?.addEventListener('click',()=>{if(currentQuestion>0){currentQuestion--;renderSeriesExam()}});
 $('#seriesEdgeNext')?.addEventListener('click',()=>{if(currentQuestion<total-1){currentQuestion++;renderSeriesExam()}else requestFinishQuiz()});
 $('#seriesSubmitTop')?.addEventListener('click',()=>requestFinishQuiz());
 $$('.mock-exam-option').forEach(btn=>btn.addEventListener('click',()=>{quizAnswers[currentQuestion]=Number(btn.dataset.seriesAnswer);renderSeriesExam()}));
 $$('.mock-question-dot').forEach(btn=>btn.addEventListener('click',()=>{currentQuestion=Number(btn.dataset.seriesQuestion);renderSeriesExam()}));
 $('#seriesPalettePrev')?.addEventListener('click',()=>{currentQuestion=Math.max(0,paletteStart-1);renderSeriesExam()});
 $('#seriesPaletteNext')?.addEventListener('click',()=>{currentQuestion=Math.min(total-1,paletteEnd);renderSeriesExam()});
 $('#seriesMarkReview')?.addEventListener('click',()=>{seriesSession.review[currentQuestion]=!seriesSession.review[currentQuestion];renderSeriesExam()});
 $('#seriesClearAnswer')?.addEventListener('click',()=>{quizAnswers[currentQuestion]=null;renderSeriesExam()});
 $('#seriesPrevious')?.addEventListener('click',()=>{if(currentQuestion>0){currentQuestion--;renderSeriesExam()}});
 $('#seriesNext')?.addEventListener('click',()=>{if(currentQuestion<total-1){currentQuestion++;renderSeriesExam()}else requestFinishQuiz()});
}
function requestFinishQuiz(){
 if(!activeQuiz||quizSubmitted)return;
 const unanswered=quizAnswers.filter(v=>v===null||v===undefined).length;
 const message=unanswered?`Submit this test with ${unanswered} unanswered question(s)? You cannot change your answers after submission.`:'Submit this test now? You cannot change your answers after submission.';
 if(!window.confirm(message))return;
 finishQuiz(false);
}
let seriesResultState=null;
function renderSeriesResultPage(){
 if(!seriesResultState)return;
 const {questions,answers,pageSize}=seriesResultState;
 const pages=Math.max(1,Math.ceil(questions.length/pageSize));
 seriesResultState.page=Math.max(0,Math.min(seriesResultState.page,pages-1));
 const start=seriesResultState.page*pageSize,end=Math.min(questions.length,start+pageSize);
 const html=questions.slice(start,end).map((q,offset)=>{
  const i=start+offset,chosen=answers[i],isBlank=chosen===null||chosen===undefined,isCorrect=!isBlank&&chosen===q.answer;
  const status=isBlank?'unanswered':isCorrect?'correct':'wrong';
  const chosenLabel=isBlank?'Not answered':(q.options?.[chosen]??'Answer unavailable');
  const correctLabel=q.options?.[q.answer]??'Answer unavailable';
  return `<article class="mock-result-question ${status}"><b>Q${i+1}. ${escapeHTML(q.q)}</b><p>Your answer: ${escapeHTML(chosenLabel)}</p><p>Correct answer: <strong>${escapeHTML(correctLabel)}</strong></p><small>${escapeHTML(q.explain||'No explanation was supplied for this question.')}</small></article>`;
 }).join('');
 const target=$('#seriesResultQuestions');if(target)target.innerHTML=html;
 const pager=$('#seriesResultPager');if(pager)pager.innerHTML=`<button class="btn btn-outline" id="seriesResultPrev" ${seriesResultState.page===0?'disabled':''}>← Previous</button><span>Showing ${start+1}–${end} of ${questions.length.toLocaleString('en-IN')} · Page ${seriesResultState.page+1}/${pages}</span><button class="btn btn-outline" id="seriesResultNext" ${seriesResultState.page>=pages-1?'disabled':''}>Next →</button>`;
 $('#seriesResultPrev')?.addEventListener('click',()=>{seriesResultState.page--;renderSeriesResultPage()});
 $('#seriesResultNext')?.addEventListener('click',()=>{seriesResultState.page++;renderSeriesResultPage()});
}
function finishQuiz(autoSubmitted=false){
 if(quizSubmitted||!activeQuiz)return;
 quizSubmitted=true;stopQuizTimer();trackStudyEvent('quiz');
 const questions=activeQuiz.questions||[],answers=Array.isArray(quizAnswers)?quizAnswers:[];
 const correct=questions.reduce((n,q,i)=>n+(answers[i]!==null&&answers[i]!==undefined&&answers[i]===q.answer?1:0),0);
 const wrong=questions.reduce((n,q,i)=>n+(answers[i]!==null&&answers[i]!==undefined&&answers[i]!==q.answer?1:0),0);
 const unanswered=Math.max(0,questions.length-correct-wrong),attempted=correct+wrong;
 quizScore=correct;
 const accuracy=attempted?Math.round(correct/attempted*100):0,points=correct*10;
 let old=0;try{old=Number(localStorage.getItem('studyspark_points')||0);localStorage.setItem('studyspark_points',String(old+points))}catch(error){console.warn('Demo points could not be saved.',error)}
 seriesResultState={questions,answers,page:0,pageSize:50};
 showModal(`<div class="mock-results-shell series-results-shell"><div class="mock-results-eyebrow">${autoSubmitted?'TIME EXPIRED · AUTO-SUBMITTED':'TEST SUBMITTED'}</div><h2 id="modalTitle">${autoSubmitted?'Your time is up.':'Test completed.'}</h2><p class="mock-results-subtitle">${escapeHTML(activeQuiz.title)} · Review your answers and explanations below.</p><div class="mock-score-hero"><div><span>CORRECT ANSWERS</span><strong>${correct}<small> / ${questions.length.toLocaleString('en-IN')}</small></strong></div><div class="mock-score-percent">${accuracy}%<small>accuracy</small></div></div><div class="mock-result-stat-grid"><div><strong>${correct.toLocaleString('en-IN')}</strong><span>Correct</span></div><div><strong>${wrong.toLocaleString('en-IN')}</strong><span>Incorrect</span></div><div><strong>${unanswered.toLocaleString('en-IN')}</strong><span>Unanswered</span></div><div><strong>+${points.toLocaleString('en-IN')}</strong><span>Practice points</span></div></div><h3 class="mock-result-heading">Answer key & explanations</h3><div class="mock-result-review"><details class="mock-result-section" open><summary><span>Question-by-question review</span><b>${questions.length.toLocaleString('en-IN')} questions</b></summary><div class="mock-result-questions" id="seriesResultQuestions"></div><div class="series-result-pager" id="seriesResultPager"></div></details></div><p class="quiz-results-local-note">Your demo points and study activity are stored only in this browser.</p><button class="btn btn-primary mock-results-home" id="seriesResultsDone">Back to StudySpark →</button></div>`);
 renderSeriesResultPage();
 $('#seriesResultsDone')?.addEventListener('click',()=>{seriesSession=null;seriesResultState=null;closeModal();renderLeaderboard();toast('Practice score saved on this device.')});
}
function renderLeaderboard(){const p=getProfile(),container=$('#leaderRows');if(!p||!container)return;const points=Number(localStorage.getItem('studyspark_points')||0);const rows=[{name:p.name,subtitle:'Your demo profile',points,initial:p.name[0]?.toUpperCase()||'Y',own:true},{name:'Aarav',subtitle:'Maths explorer',points:280,initial:'A'},{name:'Meera',subtitle:'Science thinker',points:250,initial:'M'},{name:'Rohan',subtitle:'History learner',points:210,initial:'R'}].sort((a,b)=>b.points-a.points).slice(0,4);container.innerHTML=rows.map((r,i)=>`<div class="leader-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="leader-avatar ${i===0?'lavender':i===1?'blue':i===2?'orange':'lavender'}">${r.initial}</span><span class="leader-name"><b>${escapeHTML(r.name)}${r.own?' (you)':''}</b><small>${r.subtitle}</small></span><strong>${r.points} <small>pts</small></strong></div>`).join('')}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('#viewLeaderboard')?.addEventListener('click',()=>{renderLeaderboard();$('#leaderRows')?.scrollIntoView({behavior:'smooth',block:'center'});toast('Showing sample leaderboard plus your local demo score.')});
