const polityAllAmendments = (()=>{const by=new Map(polityPdfExtraAmendments.map(a=>[a.n,a]));for(const a of polityAmendments)by.set(a.n,{...(by.get(a.n)||{}),...a});return Array.from(by.values()).sort((a,b)=>Number(a.n.replace(/\D/g,))-Number(b.n.replace(/\D/g,)));})();
