function polityChoices(correct,pool,field,offset=0){
 const correctText=String(correct),seen=new Set([correctText]),out=[correctText];
 const values=[];
 for(const item of (pool||[])){
  let value;
  if(typeof item==='string'||typeof item==='number')value=String(item);
  else if(item&&field)value=item[field];
  if(value!==undefined&&value!==null&&String(value).trim())values.push(String(value).trim());
 }
 const unique=[...new Set(values)].filter(v=>!seen.has(v));
 if(unique.length){const shift=((offset%unique.length)+unique.length)%unique.length;const rotated=unique.slice(shift).concat(unique.slice(0,shift));for(const value of rotated){if(!seen.has(value)){seen.add(value);out.push(value);if(out.length===4)break}}}
 return out;
}
function polityQuestion(q,correct,pool,field,explain,offset=0,source='Original exam-style practice · check the official Constitution for exact clause wording.'){
 const options=polityChoices(correct,pool,field,offset);
 return {q,options,answer:options.indexOf(String(correct)),explain,source};
}
function makePolityArticleQuiz(a,index){
 const key='polityArticle'+a.n.replace(/[^A-Za-z0-9]/g,'');
 const others=polityAllArticles.filter(x=>x.n!==a.n);
 const samePart=others.filter(x=>x.part===a.part);
 const articlePool=others.map(x=>'Article '+x.n);
 const titlePool=others.filter(x=>x.title&&x.title!==a.title);
 const summaryPool=others.filter(x=>x.summary&&x.summary!==a.summary);
 const factPool=others.filter(x=>x.fact&&x.fact!==a.fact);
 const keywordPool=others.filter(x=>x.keyword&&x.keyword!==a.keyword);
 const partPool=[...new Set(others.map(x=>x.part))].filter(x=>x!==a.part);
 const pointPool=others.flatMap(x=>Array.isArray(x.points)?x.points:[]).filter(Boolean);
 const tipPool=others.map(x=>x.tip).filter(Boolean);
 const points=Array.isArray(a.points)&&a.points.length?a.points:[a.fact||a.summary];
 const coreFact=a.fact||a.summary;
 const examTip=a.tip||('Do not confuse the subject of Article '+a.n+' with provisions dealing with a different constitutional issue.');
 const sibling=samePart[(index+2)%Math.max(1,samePart.length)];
 const wrongPair=samePart.find(x=>x.n!==sibling?.n&&x.title!==a.title)||others.find(x=>x.title!==a.title);
 const correctPair='Article '+a.n+' — '+a.title;
 const pairOptions=[correctPair,
  'Article '+a.n+' — '+(wrongPair?.title||a.keyword),
  'Article '+(sibling?.n||others[(index+4)%others.length]?.n||'14')+' — '+a.title,
  'Article '+(others[(index+7)%others.length]?.n||'21')+' — '+(wrongPair?.title||a.keyword)];
 const questions=[
  polityQuestion('APPLICATION: A constitutional problem turns on the following rule: “'+a.summary+'” Which provision should be examined first?','Article '+a.n,articlePool,null,'The supplied constitutional outline associates this rule with Article '+a.n+' — '+a.title+'.',index),
  polityQuestion('INTERPRETATION: Which statement most precisely reflects the legal scope or qualification recorded for Article '+a.n+'?',coreFact,factPool,'fact','The key qualification is: '+coreFact,index+1),
  polityQuestion('EXAM TRAP: Which caution should a candidate apply before selecting Article '+a.n+' in a close-option question?',examTip,tipPool,null,'The study note flags this distinction: '+examTip,index+2),
  polityQuestion('SYNTHESIS: Which option best captures the central subject after considering the provision summary and its listed points?',a.summary,summaryPool,'summary','Taken together, the listed points are summarised as: '+a.summary,index+3),
  polityQuestion('DOCTRINAL CUE: Which phrase is the most reliable keyword association for Article '+a.n+'?',a.keyword,keywordPool,'keyword','The key association recorded for Article '+a.n+' is “'+a.keyword+'”.',index+4),
  polityQuestion('STATEMENT CHECK: Which proposition is directly supported by the detailed notes for Article '+a.n+'?',points[0],pointPool,null,'The notes specifically state: '+points[0],index+5),
  polityQuestion('CONSTITUTIONAL STRUCTURE: In a question asking you to classify this provision by Part, which placement is correct?',a.part,partPool,null,'Article '+a.n+' is placed in '+a.part+'.',index+6),
  {q:'MATCH THE PROVISION: Which Article–subject pair is correctly matched?',options:pairOptions,answer:0,explain:'Article '+a.n+' is headed “'+a.title+'”. The other combinations mismatch the Article number and subject.',source:'Original analytical matching practice · verify exact wording in the official Constitution.'},
  polityQuestion(sibling?'COMPARISON: Which other provision is grouped with Article '+a.n+' in the same constitutional Part?':'CLASSIFICATION: Which Part contains Article '+a.n+'?',sibling?'Article '+sibling.n:'Article '+a.n,sibling?samePart.map(x=>'Article '+x.n):articlePool,null,sibling?'Both provisions are placed in '+a.part+'.':'The indexed provision is placed in '+a.part+'.',index+8),
  polityQuestion('PRECISION CHECK: Which statement should be retained as the most specific fact for Article '+a.n+' rather than relying on a broad one-line label?',coreFact,factPool,'fact','The specific point recorded for this provision is: '+coreFact,index+9)
 ];
 // Ensure each question has four distinct options, even for sparsely populated Parts.
 for(const q of questions){
  if(!Array.isArray(q.options)||q.options.length!==4||new Set(q.options).size!==4){
   const fallback=polityAllArticles.filter(x=>x.n!==a.n);
   const correct=String(q.options?.[q.answer]??a.title);
   q.options=polityChoices(correct,fallback,'title',index+questions.indexOf(q));
   q.answer=q.options.indexOf(correct);
  }
 }
 quizzes[key]={title:'Article '+a.n+' · '+a.title,category:'General Awareness · Polity',questions};
 return {...a,polityType:'article',quizKey:key,desc:a.summary,body:'',lessonPart:a.studyPart};
}
