function polityAmendmentQuestion(q,correct,pool,explain,offset=0){
 const options=polityChoices(correct,pool,null,offset);
 const fallback=[...polityAllAmendments.map(x=>x.n+' Amendment'),...Object.values(polityAmendmentAnchors),...Object.values(polityAmendmentCategories)];
 for(const candidate of fallback){if(options.length>=4)break;if(candidate!==String(correct)&&!options.includes(candidate))options.push(candidate)}
 return {q,options,answer:options.indexOf(String(correct)),explain,source:'Original exam-style practice based on your supplied amendment summary and constitutional references; not a verbatim PYQ.'};
}
function makePolityAmendmentQuiz(a,index){
 const key='polityAmendment'+a.n.replace(/[^A-Za-z0-9]/g,'');
 const all=polityAllAmendments.filter(x=>x.n!==a.n);
 const allPoints=polityAllAmendments.flatMap(x=>x.points||[]).filter(Boolean);
 const allAnchors=Object.entries(polityAmendmentAnchors).filter(([n])=>n!==a.n).map(([,v])=>v);
 const allCategories=[...new Set(Object.entries(polityAmendmentCategories).filter(([n])=>n!==a.n).map(([,v])=>v))];
 const pair=polityAllAmendments.find(x=>x.n===polityAmendmentPairs[a.n]);
 const pairedOptions=pair?[
  `${a.n} Amendment — ${a.keyword}  |  ${pair.n} Amendment — ${pair.keyword}`,
  `${a.n} Amendment — ${pair.keyword}  |  ${pair.n} Amendment — ${a.keyword}`,
  `${a.n} Amendment — ${a.keyword}  |  ${pair.n} Amendment — ${all.find(x=>x.n!==pair.n)?.keyword||'unrelated subject'}`,
  `${a.n} Amendment — ${all.find(x=>x.n!==pair.n)?.keyword||'unrelated subject'}  |  ${pair.n} Amendment — ${pair.keyword}`
 ]:[];
 const questions=[
  polityAmendmentQuestion('Which Constitutional Amendment is associated with this change: '+a.summary,a.n+' Amendment',all.map(x=>x.n+' Amendment'),'The '+a.n+' Amendment ('+a.year+') is associated with this change: '+a.summary,index),
  polityAmendmentQuestion('In which year was the '+a.n+' Constitutional Amendment enacted?',a.year,all.map(x=>x.year),'The '+a.n+' Constitutional Amendment is dated '+a.year+'.',index+1),
  polityAmendmentQuestion('What is the principal subject of the '+a.n+' Amendment?',a.summary,all.map(x=>x.summary),'Its principal subject in your study entry is: '+a.summary,index+2),
  polityAmendmentQuestion('Which key association is linked with the '+a.n+' Amendment?',a.keyword,all.map(x=>x.keyword),'The key association listed for this amendment is “'+a.keyword+'”.',index+3),
  polityAmendmentQuestion('Which statement about the '+a.n+' Amendment is accurate?',a.fact,all.map(x=>x.fact),'The accurate statement is: '+a.fact,index+4),
  polityAmendmentQuestion('Which feature is explicitly listed first among the effects of the '+a.n+' Amendment?',a.points[0],allPoints,'The supplied entry lists this feature: '+a.points[0],index+5),
  polityAmendmentQuestion('Which additional detail is included in the notes for the '+a.n+' Amendment?',a.points[1],allPoints,'Another detail listed in the entry is: '+a.points[1],index+6),
  polityAmendmentQuestion('Which further point appears in the study entry for the '+a.n+' Amendment?',a.points[2],allPoints,'The entry also records: '+a.points[2],index+7),
  polityAmendmentQuestion('Which constitutional provision, Schedule or arrangement is most directly linked to the '+a.n+' Amendment?',polityAmendmentAnchors[a.n]||a.keyword,allAnchors,'The key constitutional anchor in this study set is: '+(polityAmendmentAnchors[a.n]||a.keyword)+'.',index+8),
  polityAmendmentQuestion('Which exam distinction should you remember about the '+a.n+' Amendment?',a.tip,all.map(x=>x.tip),'The important distinction is: '+a.tip,index+9),
  polityAmendmentQuestion('Select the correctly matched Amendment–year–theme combination.',`${a.n} Amendment (${a.year}) — ${a.keyword}`,all.map(x=>`${x.n} Amendment (${x.year}) — ${x.keyword}`),'The correct match is '+a.n+' Amendment, '+a.year+', associated with '+a.keyword+'.',index+10),
  polityAmendmentQuestion(pair?'Which option correctly distinguishes the '+a.n+' Amendment from the '+pair.n+' Amendment?':'Which revision category best fits the '+a.n+' Amendment?',pair?pairedOptions[0]:polityAmendmentCategories[a.n],pair?pairedOptions.slice(1):allCategories,pair?('The '+a.n+' Amendment is associated with '+a.keyword+', while the '+pair.n+' Amendment is associated with '+pair.keyword+'.'):'This entry belongs in the revision category “'+polityAmendmentCategories[a.n]+'”; its specific constitutional effect is: '+a.summary,index+11)
 ];
 // Validate each item without changing its intended correct answer.
 const expected=[a.n+' Amendment',a.year,a.summary,a.keyword,a.fact,a.points[0],a.points[1],a.points[2],polityAmendmentAnchors[a.n]||a.keyword,a.tip,`${a.n} Amendment (${a.year}) — ${a.keyword}`,pair?pairedOptions[0]:polityAmendmentCategories[a.n]];
 const generalFallback=polityAllAmendments.filter(x=>x.n!==a.n).flatMap(x=>[x.n+' Amendment',x.summary,x.keyword,x.fact,...(x.points||[])]);
 questions.forEach((q,i)=>{
  const correct=String(expected[i]);
  const options=[correct,...(q.options||[]).filter(v=>String(v)!==correct).map(String),...generalFallback.map(String)].filter((v,j,arr)=>v&&arr.indexOf(v)===j).slice(0,4);
  if(options.length!==4)throw new Error('Amendment question options incomplete: '+a.n+' / '+(i+1));
  q.options=options;
  q.answer=options.indexOf(correct);
  if(q.answer<0)throw new Error('Amendment answer key missing: '+a.n+' / '+(i+1));
 });
 quizzes[key]={title:a.n+' Amendment · '+a.year,category:'General Awareness · Polity',questions};
 return {...a,polityType:'amendment',quizKey:key,desc:a.summary,body:'',lessonPart:index};
}
