   if(topic){const next=Number(topic.dataset.algebraTopic);if(Number.isInteger(next)&&next>=0&&next<algebraRevisionLessons.length){currentIndex=next;render()}return}
   if(e.target.closest('[data-algebra-fast-start]')){trackStudyEvent('test');startQuiz('algebraRevisionFastTest');return}
   if(e.target.closest('[data-algebra-complete-start]')){trackStudyEvent('test');startQuiz('algebraCompleteRevisionTest');return}
   if(e.target.closest('[data-algebra-source-start]')){trackStudyEvent('test');startQuiz('algebraPdfCoverageTest');return}
