function openTopicFolder(subject,folder,backAction){
 if(subject==='Maths' && folder.title==='Algebra Revision'){openAlgebraRevisionWorkspace(backAction);return;}
 if(folder.polityDeck && folder.children && folder.children.length){trackStudyEvent('notes');openChapterLesson(subject,folder.children[0],folder.title,backAction,folder.children,0);return;}
 const is120Folder = subject==='English' && /120 Rules of English Grammar/i.test(folder.title);
 // Keep the 120 Rules experience simple: opening the folder starts Rule 1 as a slide.
 // Previous/Next moves through the existing source-ordered rule list.
 if(is120Folder && folder.children && folder.children.length){
   openChapterLesson(subject,folder.children[0],folder.title,backAction,folder.children,0);
   return;
 }
 const folderTestSubject = is120Folder ? 'English' : (subject==='GK' && /Polity|Lecture 1|Articles|Amendments/i.test(folder.title) ? 'General Awareness' : subject==='Maths' ? 'Mathematics' : subject==='Reasoning' ? 'Reasoning' : subject==='GK' ? 'General Awareness' : 'All subjects');
 const folderTestGK = subject==='GK' && /Criminal Law|BNS|BNSS|BSA/i.test(folder.title) ? 'Criminal Law' : subject==='GK' && /Polity|Lecture 1|Articles|Amendments/i.test(folder.title) ? 'Polity' : 'All GK';
 const algebraRevisionShortcut = subject==='Maths' && folder.title==='Algebra Revision' ? `<section class="central-test-redirect algebra-fast-test-shortcut"><div><span class="eyebrow">ALGEBRA REVISION WORKSPACE</span><h3>All nine concepts in one place</h3><p>Open the workspace card below to switch between all nine concept tabs and launch the 28-, 52- or 60-question Algebra test.</p></div></section>` : '';
 const testShortcuts = algebraRevisionShortcut || ((is120Folder || subject==='GK' && (/Indian Polity|Lecture 1 Notes|Criminal Law/i.test(folder.title))) ? `<section class="central-test-redirect"><div><span class="eyebrow">MOCK TEST CENTRE</span><h3>Practice tests are organised in one place</h3><p>Open the central test hub for the matching subject, sectionals and topic quizzes.</p></div><button class="btn btn-primary" data-open-central-tests="${folderTestSubject}" data-open-central-gk="${folderTestGK}">Open Mock Test Centre →</button></section>` : '');
 const isPolityFolder=subject==='GK'&&/^(Indian Polity|Articles of the Constitution|Constitutional Amendments|Lecture 1 Notes|Part [1-4]\b)/.test(folder.title);
 showModal(`<div class="topic-folder-workspace ${isPolityFolder?'polity-topic-folder':''}"><div class="eyebrow">${escapeHTML(subject.toUpperCase())} · ${isPolityFolder?'INDIAN POLITY':'TOPIC'}</div><button class="summary-page-back folder-back-top" id="folderBackTop">← Back to previous page</button><h2 id="modalTitle">${escapeHTML(folder.title)}</h2><p>Choose a chapter to open its notes. Use the back button to return to the previous folder.</p>${testShortcuts}<div class="portal-grid">${folder.children.map((c,i)=>`<article class="portal-card"><span class="portal-number">${c.children?'FOLDER':'CHAPTER'} ${String(i+1).padStart(2,'0')}</span><h3>${escapeHTML(c.title)}</h3><p>${escapeHTML(c.desc||'Study notes and revision.')}</p>${c.polityType?`<div class="polity-card-meta"><span>${c.polityType==='lecture'?'Lecture slide':c.polityType==='article'?'10 MCQs':'5 MCQs'}</span><span>${c.polityType==='lecture'?'Handwritten notes':'One-line takeaway'}</span><span>Previous / Next</span></div>`:''}<button class="btn btn-outline" data-folder-child="${i}">${c.quizKey?'Start test →':c.children?'Open folder →':'Read notes →'}</button></article>`).join('')}</div><button class="btn btn-outline" id="backToParent">← Back</button></div>`);
 $('#backToParent').onclick=backAction;
 $('#folderBackTop')?.addEventListener('click',()=>backAction?.());
 $('#modalContent').onclick=e=>{const algebraFast=e.target.closest('[data-start-algebra-revision]');if(algebraFast){startQuiz('algebraRevisionFastTest');return}const central=e.target.closest('[data-open-central-tests]');if(central){closeModal();openCglMockHub('topics',central.dataset.openCentralTests,central.dataset.openCentralGk||'All GK');return}const b=e.target.closest('[data-folder-child]');if(!b)return;const idx=Number(b.dataset.folderChild);const child=folder.children[idx];if(child.algebraRevisionWorkspace){openChapterLesson(subject,algebraRevisionLessons[0],folder.title,()=>openTopicFolder(subject,folder,backAction),algebraRevisionLessons,0);return}if(child.quizKey){startQuiz(child.quizKey);return}if(child.children)openTopicFolder(subject,child,()=>openTopicFolder(subject,folder,backAction));else{trackStudyEvent('notes');openChapterLesson(subject,child,folder.title,()=>openTopicFolder(subject,folder,backAction),folder.children,idx)}};
}
