function openMockGrammarPicker(){
 const resumeBanner=seriesSession?.paused?`<div class="paused-attempt-banner"><div><span>PAUSED ATTEMPT</span><b>${escapeHTML(activeQuiz?.title||'English practice')}</b><small>${formatQuizTime(seriesSession.remainingSeconds)} remaining · Your answers are saved</small></div><button class="btn btn-primary" id="resumeSeriesAttempt">Resume test →</button></div>`:'';
 showModal(`<div class="mock-topic-browser"><div class="eyebrow">ENGLISH · GRAMMAR</div><h2 id="modalTitle">120 Rules · Practice Tests</h2><p>Choose one of the four rule ranges. Each part contains 30 source topics with 15 questions per topic (450 questions total).</p>${resumeBanner}<div class="mock-grammar-part-grid">${[1,2,3,4].map(part=>`<article class="mock-grammar-part-card"><span>PART ${part}</span><b>Rules ${(part-1)*30+1}–${part*30}</b><small>450-question bank · 15 per topic · shuffled for each attempt</small><button class="btn btn-primary" data-mock-grammar-part="${part}">Start Part ${part} →</button></article>`).join('')}</div><button class="btn btn-outline" id="mockGrammarBack">← Back to Mock Test Centre</button></div>`);
 $('#resumeSeriesAttempt')?.addEventListener('click',resumeSeriesAttempt);
 $('#mockGrammarBack')?.addEventListener('click',()=>openCglMockHub('topics','English'));
 $$('[data-mock-grammar-part]').forEach(b=>b.addEventListener('click',()=>startQuiz('grammar120part'+b.dataset.mockGrammarPart)));
}
